async function e(){const o=await fetch("/api/kbs");if(o.status===401)throw new Error("UNAUTHORIZED");if(!o.ok)throw new Error("HTTP "+o.status);return o.json()}async function a(o){const t=await fetch("/api/kbs",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(o)});if(t.status===401)throw new Error("UNAUTHORIZED");if(!t.ok)throw new Error("HTTP "+t.status);return t.json()}async function c(o){const t=await fetch(`/api/kbs/${encodeURIComponent(o)}`,{method:"DELETE"});if(t.status===401)throw new Error("UNAUTHORIZED");if(!t.ok)throw new Error("HTTP "+t.status);return t.json()}async function i(o){const t=await fetch(`/api/kbs/${encodeURIComponent(o)}/reindex`,{method:"POST"});if(t.status===401)throw new Error("UNAUTHORIZED");if(!t.ok)throw new Error("HTTP "+t.status);return t.json()}async function w(o){const t=await fetch(`/api/kbs/${encodeURIComponent(o)}/docs`);if(t.status===401)throw new Error("UNAUTHORIZED");if(!t.ok)throw new Error("HTTP "+t.status);return t.json()}async function f(o,t){const n=new FormData;n.append("file",t);const r=await fetch(`/api/kbs/${encodeURIComponent(o)}/docs`,{method:"POST",body:n});if(r.status===401)throw new Error("UNAUTHORIZED");if(!r.ok){const s=await r.json().catch(()=>({}));throw new Error(typeof s.detail=="string"?s.detail:"HTTP "+r.status)}return r.json()}async function h(o,t){const n=await fetch(`/api/kbs/${encodeURIComponent(o)}/docs/${encodeURIComponent(t)}`,{method:"DELETE"});if(n.status===401)throw new Error("UNAUTHORIZED");if(!n.ok)throw new Error("HTTP "+n.status);return n.json()}async function u(o,t=50){const n=await fetch(`/api/kbs/${encodeURIComponent(o)}/tasks?limit=${t}`);if(n.status===401)throw new Error("UNAUTHORIZED");if(!n.ok)throw new Error("HTTP "+n.status);return n.json()}export{c as a,w as b,a as c,h as d,u as e,e as f,i as r,f as u};
